1	import { expect, test } from "bun:test";
2	import { runInMicroVm } from "../../src/sandbox/microvm.ts";
3	
4	type ExecResult = { code: number; stdout: string; stderr: string };
5	
6	function makeClient(
7	  execImpl?: (cmd: string[], callIndex: number) => ExecResult | Promise<ExecResult>
8	) {
9	  const events: Array<{
10	    kind: "create" | "write" | "exec" | "stop";
11	    path?: string;
12	    content?: string;
13	    cmd?: string[];
14	    timeoutMs?: number;
15	  }> = [];
16	  const state = { createCalls: 0, stopCalls: 0 };
17	
18	  return {
19	    events,
20	    state,
21	    async create(): Promise<{ id: string }> {
22	      state.createCalls += 1;
23	      events.push({ kind: "create" });
24	      return { id: "vm-1" };
25	    },
26	    async write(_id: string, path: string, content: string): Promise<void> {
27	      events.push({ kind: "write", path, content });
28	    },
29	    async exec(_id: string, cmd: string[], timeoutMs: number): Promise<ExecResult> {
30	      events.push({ kind: "exec", cmd: [...cmd], timeoutMs });
31	      const callIndex = events.filter((e) => e.kind === "exec").length;
32	      if (execImpl) return execImpl(cmd, callIndex);
33	      return { code: 0, stdout: "", stderr: "" };
34	    },
35	    async stop(_id: string): Promise<void> {
36	      state.stopCalls += 1;
37	      events.push({ kind: "stop" });
38	    },
39	  };
40	}
41	
42	test("rejects non-https repo URLs before creating anything", async () => {
43	  const client = makeClient();
44	
45	  await expect(
46	    runInMicroVm(
47	      {
48	        repoUrl: "[REDACTED_EMAIL]:owner/repo.git",
49	        command: ["true"],
50	        timeoutMs: 5000,
51	        files: { "README.md": "hi" },
52	      },
53	      client
54	    )
55	  ).rejects.toThrow();
56	
57	  expect(client.state.createCalls).toBe(0);
58	  expect(client.state.stopCalls).toBe(0);
59	  expect(client.events).toEqual([]);
60	});
61	
62	test("creates VM, writes files, clones, runs command, and stops", async () => {
63	  const client = makeClient((_cmd, callIndex) => {
64	    if (callIndex === 1) return { code: 0, stdout: "clone ok", stderr: "" };
65	    return { code: 0, stdout: "command out", stderr: "" };
66	  });
67	
68	  const result = await runInMicroVm(
69	    {
70	      repoUrl: "https://github.com/owner/repo.git",
71	      command: ["pwd"],
72	      timeoutMs: 10000,
73	      files: { "README.md": "hello", "src/main.ts": "console.log('hi')" },
74	    },
75	    client
76	  );
77	
78	  expect(result).toEqual({ code: 0, stdout: "command out", stderr: "", timedOut: false });
79	  expect(client.state.createCalls).toBe(1);
80	  expect(client.state.stopCalls).toBe(1);
81	  expect(client.events.map((e) => e.kind)).toEqual(["create", "write", "write", "exec", "exec", "stop"]);
82	
83	  const execEvents = client.events.filter((e) => e.kind === "exec");
84	  expect(execEvents).toHaveLength(2);
85	  expect(execEvents[0]?.cmd).toEqual(["git", "clone", "--filter=blob:none", "https://github.com/owner/repo.git", "/work"]);
86	  expect(execEvents[0]?.timeoutMs).toBe(10000);
87	  expect(execEvents[1]?.timeoutMs).toBe(10000);
88	  expect(execEvents[1]?.cmd?.join(" ")).toContain("pwd");
89	
90	  const writeEvents = client.events.filter((e) => e.kind === "write");
91	  expect(writeEvents).toEqual([
92	    { kind: "write", path: "README.md", content: "hello" },
93	    { kind: "write", path: "src/main.ts", content: "console.log('hi')" },
94	  ]);
95	});
96	
97	test("does not write files when none are provided", async () => {
98	  const client = makeClient();
99	
100	  await runInMicroVm(
101	    {
102	      repoUrl: "https://github.com/owner/repo.git",
103	      command: ["ls"],
104	      timeoutMs: 5000,
105	    },
106	    client
107	  );
108	
109	  expect(client.events.map((e) => e.kind)).toEqual(["create", "exec", "exec", "stop"]);
110	  expect(client.events.filter((e) => e.kind === "write")).toEqual([]);
111	});
112	
113	test("returns clone failure, does not run the command, and still stops", async () => {
114	  const client = makeClient((_cmd, callIndex) => {
115	    if (callIndex === 1) return { code: 128, stdout: "", stderr: "fatal clone" };
116	    return { code: 0, stdout: "should not run", stderr: "" };
117	  });
118	
119	  const result = await runInMicroVm(
120	    {
121	      repoUrl: "https://github.com/owner/repo.git",
122	      command: ["false"],
123	      timeoutMs: 5000,
124	    },
125	    client
